insert into kotes.quotes (body, author, source, tags) values
  ('The happiness of your life depends upon the quality of your thoughts.', 'Marcus Aurelius', 'Meditations', array['stoic', 'wisdom']::text[]),
  ('We suffer more often in imagination than in reality.', 'Seneca', 'Letters to Lucilius', array['stoic', 'courage']::text[]),
  ('Waste no more time arguing about what a good man should be. Be one.', 'Marcus Aurelius', 'Meditations', array['stoic', 'ambition']::text[]),
  ('It is not that we have a short time to live, but that we waste a lot of it.', 'Seneca', 'On the Shortness of Life', array['stoic', 'time']::text[]),
  ('No man is free who is not master of himself.', 'Epictetus', null, array['stoic', 'wisdom']::text[]),
  ('First say to yourself what you would be; and then do what you have to do.', 'Epictetus', 'Discourses', array['stoic', 'ambition']::text[]),
  ('The impediment to action advances action. What stands in the way becomes the way.', 'Marcus Aurelius', 'Meditations', array['stoic', 'courage']::text[]),
  ('Difficulties strengthen the mind, as labor does the body.', 'Seneca', null, array['stoic', 'courage']::text[]),
  ('Very little is needed to make a happy life; it is all within yourself, in your way of thinking.', 'Marcus Aurelius', 'Meditations', array['stoic', 'wisdom']::text[]),
  ('Wealth consists not in having great possessions, but in having few wants.', 'Epictetus', null, array['stoic', 'wisdom']::text[]),
  ('One must imagine Sisyphus happy.', 'Albert Camus', 'The Myth of Sisyphus', array['stoic', 'hope']::text[]),
  ('There is nothing either good or bad, but thinking makes it so.', 'William Shakespeare', 'Hamlet', array['stoic', 'wisdom']::text[]),
  ('The two most powerful warriors are patience and time.', 'Leo Tolstoy', 'War and Peace', array['stoic', 'time']::text[]),
  ('I exist as I am, that is enough.', 'Walt Whitman', 'Song of Myself', array['stoic', 'solitude']::text[]),
  ('Whatever our souls are made of, his and mine are the same.', 'Emily Brontë', 'Wuthering Heights', array['love']::text[]),
  ('I have loved the stars too fondly to be fearful of the night.', 'Sarah Williams', 'The Old Astronomer', array['love', 'nature', 'courage']::text[]),
  ('Love is composed of a single soul inhabiting two bodies.', 'Aristotle', null, array['love', 'wisdom']::text[]),
  ('The course of true love never did run smooth.', 'William Shakespeare', 'A Midsummer Night''s Dream', array['love']::text[]),
  ('Doubt thou the stars are fire; doubt that the sun doth move; doubt truth to be a liar; but never doubt I love.', 'William Shakespeare', 'Hamlet', array['love']::text[]),
  ('You pierce my soul. I am half agony, half hope.', 'Jane Austen', 'Persuasion', array['love', 'hope', 'melancholy']::text[]),
