  ('The supreme happiness of life is the conviction that we are loved.', 'Victor Hugo', 'Les Misérables', array['love', 'hope']::text[]),
  ('We loved with a love that was more than love.', 'Edgar Allan Poe', 'Annabel Lee', array['love', 'melancholy']::text[]),
