  ('The heart has its reasons which reason knows nothing of.', 'Blaise Pascal', 'Pensées', array['love', 'wisdom']::text[]),
  ('What we have once enjoyed we can never lose; all that we love deeply becomes a part of us.', 'Helen Keller', null, array['love', 'time']::text[]),
  ('She wasn''t doing a thing that I could see, except standing there leaning on the balcony railing, holding the universe together.', 'J. D. Salinger', 'A Girl I Knew', array['love', 'art']::text[]),
  ('Parting is all we know of heaven, and all we need of hell.', 'Emily Dickinson', null, array['love', 'melancholy']::text[]),
  ('Gather ye rosebuds while ye may, old Time is still a-flying.', 'Robert Herrick', 'To the Virgins, to Make Much of Time', array['love', 'time']::text[]),
  ('I never found the companion that was so companionable as solitude.', 'Henry David Thoreau', 'Walden', array['solitude']::text[]),
  ('I went to the woods because I wished to live deliberately, to front only the essential facts of life.', 'Henry David Thoreau', 'Walden', array['solitude', 'nature']::text[]),
